// UDP health check.
// It has 2 behaviors:
//   - if receive is not empty, it sends the payload and checks that the datagrams received back match receive.
//   - (Weak method) if receive is empty, it first pings the host with ICMP and marks it unhealthy when there is no
//     reply. Otherwise it sends the payload and waits up to `timeout` for an ICMP unreachable message about the host or
//     port. The endpoint is unhealthy when one arrives and healthy when none does.
type UdpHealthCheck struct {
	state protoimpl.MessageState `protogen:"open.v1"`
	// Payload to send. Something is always sent, so the agent sends a default payload when it is left empty.
	Send *HealthCheckPayload `protobuf:"bytes,1,opt,name=send,proto3" json:"send,omitempty"`
	// Expected datagrams. Each block is read from the next datagram received, waiting up to `timeout`, and must equal
	// its first bytes.
	Receive []*HealthCheckPayload `protobuf:"bytes,2,rep,name=receive,proto3" json:"receive,omitempty"`
	// PingTimeout specifies the timeout of the ICMP ping of the weak method. Defaults to 5s.
	PingTimeout *durationpb.Duration `protobuf:"bytes,3,opt,name=ping_timeout,json=pingTimeout,proto3" json:"ping_timeout,omitempty"`
	// Delay is how long each read of the ICMP socket waits before reading again, in the weak method. Defaults to 1s.
	Delay         *durationpb.Duration `protobuf:"bytes,4,opt,name=delay,proto3" json:"delay,omitempty"`
	unknownFields protoimpl.UnknownFields
	sizeCache     protoimpl.SizeCache
}

